create or replace function public.can_participate_community_activity(p_activity text) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare v_uid uuid:=auth.uid(); v_tier text; begin if p_activity='game' then return true; end if; if v_uid is null then return false; end if; select subscription_tier::text into v_tier from public.profiles where id=v_uid; return v_tier in ('premium','family','fleet','enterprise'); end; $$; grant execute on function public.can_participate_community_activity(text) to anon, authenticated;
